// Auto-save token ke environment setelah login berhasil
if (pm.response.code === 200) {
    const body = pm.response.json();
    pm.environment.set('ACCESS_TOKEN', body.data.access_token);
    pm.environment.set('REFRESH_TOKEN', body.data.refresh_token);
    pm.environment.set('TOKEN_EXPIRY', Date.now() + (body.data.expires_in * 1000));
    console.log('[Login] Token tersimpan. Expired dalam', body.data.expires_in, 'detik');
}

if (pm.response.code === 200) {
    const body = pm.response.json();
    pm.environment.set('ACCESS_TOKEN', body.data.access_token);
    pm.environment.set('TOKEN_EXPIRY', Date.now() + (body.data.expires_in * 1000));
    console.log('[Refresh] Token diperbarui.');
}

if (pm.response.code === 200) {
    pm.environment.set('ACCESS_TOKEN', '');
    pm.environment.set('REFRESH_TOKEN', '');
    pm.environment.set('TOKEN_EXPIRY', '');
    console.log('[Logout] Token dihapus dari environment.');
}
